pageCss:
.theory-body {
  padding: 80px 48px 120px;
  background: var(--cream);
}
.theory-body .container {
  max-width: 720px;
  margin: 0 auto;
}
.theory-stat {
  background: var(--navy-dark);
  color: var(--white);
  border-radius: 12px;
  padding: 36px 40px;
  margin-bottom: 64px;
}
.theory-stat p {
  font-size: 20px;
  line-height: 1.6;
  margin: 0;
  color: rgba(255,255,255,0.9);
}
.theory-stat strong {
  color: var(--white);
  font-weight: 800;
}
.theory-section {
  margin-bottom: 56px;
}
.theory-section h2 {
  font-size: 24px;
  font-weight: 800;
  color: var(--navy-dark);
  letter-spacing: -0.02em;
  margin-bottom: 20px;
  padding-bottom: 12px;
  border-bottom: 2px solid rgba(0,0,0,0.08);
}
.theory-section p {
  font-size: 17px;
  line-height: 1.8;
  color: #2c2c2c;
  margin-bottom: 18px;
}
.theory-section p:last-child {
  margin-bottom: 0;
}
@media (max-width: 600px) {
  .theory-body { padding: 56px 24px 80px; }
  .theory-stat { padding: 28px 24px; }
  .theory-stat p { font-size: 17px; }
}
